reports.queryTemplate:
SELECT RI_ReportNo `Report No`,DATE_FORMAT(RI_DATE,'%d-%m-%Y') `Date`,RD_BATCHNO `Batch No`,MM_RawMtpartNo `Raw Material`,MT_NAME `Material Name`,RD_Qty `Scrap Qty(kg)`,RD_Remarks `Remarks`
FROM rm_inwardmaster inner join rm_inwarddetails on RD_RIID = RI_ID inner join materialmaster on MM_Id = RD_RMID inner join materialtypemaster on mm_mtid = mt_id
where RI_Movement='O' and RI_MovementType=8 and  MONTH(RI_DATE)={Month} and YEAR(RI_DATE)={Year}

SELECT
    MT_Name AS Material_Type,
    SUM(RH_QTY) AS Total_RM_Stock
FROM rm_stockhistory
LEFT JOIN materialmaster      ON mm_id   = RH_RMID
LEFT JOIN materialtypemaster  ON MM_mtId = MT_Id
LEFT JOIN rm_movements        ON ML_ID   = RH_MLID
WHERE RH_MONTH = {month}
  AND RH_YEAR  = {year}
  AND RH_WEEK  = {week}
  AND RH_MLID in (2,3,4,9)
GROUP BY MT_Name
ORDER BY MT_Name;

select MCM_Name 'MachineName',  sum(PD_PRODQTY) 'Prod Qty' , round(sum(PD_PRODQTY/(CT_NO_OF_CAVITY*TL_spm))/60,4) 'Duration(Hrs)', round(sum(PD_PRODQTY/(CT_NO_OF_CAVITY*TL_spm))*100/(175*60),4) 'Est Usage Percent',
count(distinct(PD_TOOLID)) 'Distinct Parts',count(distinct(PD_OPID)) 'Distinct Operators'  
from  machinemaster
left join production_details on mcm_id = PD_MCID
left join tool_life on PD_TOOLID=TL_tool_id
left join components_tool on PD_TOOLID =ct_id
where month(PD_DATE) = {month}
and  year(PD_DATE) = {year}
group by PD_MCID
order by MCM_Name;

select MCM_Name Machine,DATE_FORMAT(pd_date, '%d-%m-%Y')'Prod Date',co_partno 'Part No',PD_PRODQTY Qty, CT_TOOLNO ToolNo, coalesce(TL_spm,0) SPM,CT_NO_OF_CAVITY Cavity, round(PD_PRODQTY/(CT_NO_OF_CAVITY*TL_spm)/60 ,4)DurationInHrs,OP_NAME Operator
from production_details
left join machinemaster  on mcm_id = PD_MCID
left join tool_life on PD_TOOLID=TL_tool_id
left join components_tool on PD_TOOLID =ct_id
left join components on co_id = CT_COMPID
left join operators on OP_ID=PD_OPID
where month(PD_DATE) ={month}
and  year(PD_DATE) = {year}
and mcm_name = {MachineName}
and co_partno = {PartNo}

select MCM_Name Machine,DATE_FORMAT(pd_date, '%d-%m-%Y')'Prod Date',co_partno 'Part No',PD_PRODQTY Qty, CT_TOOLNO ToolNo, coalesce(TL_spm,0) SPM,CT_NO_OF_CAVITY Cavity, round(PD_PRODQTY/(CT_NO_OF_CAVITY*TL_spm)/60 ,4)DurationInHrs,OP_NAME Operator
from production_details
left join machinemaster  on mcm_id = PD_MCID
left join tool_life on PD_TOOLID=TL_tool_id
left join components_tool on PD_TOOLID =ct_id
left join components on co_id = CT_COMPID
left join operators on OP_ID=PD_OPID
where month(PD_DATE) ={month}
and  year(PD_DATE) = {year}
and mcm_name = {MachineName}

select OP_NAME Operator,sum(PD_PRODQTY ) Qty, sum(PD_SFREJECT) RejectQty, sum(PD_SWQTY) SWQty, count(distinct(PD_MCID)) 'Distinct Machines', count(distinct(PD_PSID)) 'Distinct Parts'
from  operators 
left join production_details on OP_ID=PD_OPID
where month(PD_DATE) = {month}
and  year(PD_DATE) = {year}
group by op_id
order by OP_NAME;

select op_Name Operator, CO_PARTNO PartNo,PD_LotNo LotNo,DATE_FORMAT(pd_date, '%d-%m-%Y')'Prod Date', PD_BATCHNO Batch,CT_TOOLNO Tool, PD_PRODQTY ProdQty,PD_SFREJECT SFReject, PD_SWQTY SWQty  from production_details
left join operators on op_id = pd_opid
left join components_tool on PD_TOOLID = ct_id
left join components on CT_COMPID = co_id
where  month(PD_DATE) = {month}
and  year(PD_DATE) = {year}
and op_name={Operator};
